function S(t,l=14){if(t.length<l+1)return[];const a=new Array(t.length).fill(null);let s=0,h=0;for(let c=1;c<=l;c++){const g=t[c]-t[c-1];g>0?s+=g:h-=g}let n=s/l,u=h/l;a[l]=u===0?100:100-100/(1+n/u);for(let c=l+1;c<t.length;c++){const g=t[c]-t[c-1],r=g>0?g:0,w=g<0?-g:0;n=(n*(l-1)+r)/l,u=(u*(l-1)+w)/l,a[c]=u===0?100:100-100/(1+n/u)}return a}function B(t,l=20,a=2){const s={upper:new Array(t.length).fill(null),middle:new Array(t.length).fill(null),lower:new Array(t.length).fill(null)};for(let h=l-1;h<t.length;h++){const n=t.slice(h-l+1,h+1),u=n.reduce((r,w)=>r+w,0)/l,c=n.reduce((r,w)=>r+Math.pow(w-u,2),0)/l,g=Math.sqrt(c);s.middle[h]=u,s.upper[h]=u+a*g,s.lower[h]=u-a*g}return s}function D(t,l){const a=new Array(t.length).fill(null),s=2/(l+1);let h=0;for(let n=0;n<l&&n<t.length;n++)h+=t[n];if(t.length>=l){a[l-1]=h/l;for(let n=l;n<t.length;n++)a[n]=(t[n]-a[n-1])*s+a[n-1]}return a}function I(t,l){const a=new Array(t.length).fill(null);for(let s=l-1;s<t.length;s++){const h=t.slice(s-l+1,s+1);a[s]=h.reduce((n,u)=>n+u,0)/l}return a}function L(t,l=12,a=26,s=9){const h=D(t,l),n=D(t,a),u=new Array(t.length).fill(null);for(let o=0;o<t.length;o++)h[o]!==null&&n[o]!==null&&(u[o]=h[o]-n[o]);const c=u.filter(o=>o!==null),g=D(c,s),r=new Array(t.length).fill(null);let w=0;for(let o=0;o<t.length;o++)u[o]!==null&&(r[o]=g[w]||null,w++);const M=new Array(t.length).fill(null);for(let o=0;o<t.length;o++)u[o]!==null&&r[o]!==null&&(M[o]=u[o]-r[o]);return{macdLine:u,signalLine:r,histogram:M}}function R(t,l=14){const a=new Array(t.length).fill(null);if(t.length<l+1)return a;const s=[];for(let n=1;n<t.length;n++){const u=t[n].high,c=t[n].low,g=t[n-1].close,r=Math.max(u-c,Math.abs(u-g),Math.abs(c-g));s.push(r)}let h=s.slice(0,l).reduce((n,u)=>n+u,0)/l;a[l]=h;for(let n=l;n<s.length;n++)h=(h*(l-1)+s[n])/l,a[n+1]=h;return a}function V(t,l=14){const a=new Array(t.length).fill(null);if(t.length<l*2)return a;const s=[],h=[],n=[];for(let e=1;e<t.length;e++){const f=t[e].high,m=t[e].low,i=t[e-1].high,b=t[e-1].low,x=t[e-1].close,v=Math.max(f-m,Math.abs(f-x),Math.abs(m-x));n.push(v);const A=f-i,y=b-m;s.push(A>y&&A>0?A:0),h.push(y>A&&y>0?y:0)}const u=[],c=[],g=[];let r=n.slice(0,l).reduce((e,f)=>e+f,0),w=s.slice(0,l).reduce((e,f)=>e+f,0),M=h.slice(0,l).reduce((e,f)=>e+f,0);u.push(r),c.push(w),g.push(M);for(let e=l;e<n.length;e++)r=u[u.length-1]-u[u.length-1]/l+n[e],w=c[c.length-1]-c[c.length-1]/l+s[e],M=g[g.length-1]-g[g.length-1]/l+h[e],u.push(r),c.push(w),g.push(M);const o=[];for(let e=0;e<u.length;e++){const f=u[e]>0?c[e]/u[e]*100:0,m=u[e]>0?g[e]/u[e]*100:0,i=f+m,b=i>0?Math.abs(f-m)/i*100:0;o.push(b)}if(o.length>=l){let e=o.slice(0,l).reduce((f,m)=>f+m,0)/l;a[l*2]=e;for(let f=l;f<o.length;f++)e=(e*(l-1)+o[f])/l,a[l+1+f]=e}return a}function C(t,l=20,a=2){const s=B(t,l,a),h=new Array(t.length).fill(null);for(let n=0;n<t.length;n++)if(s.upper[n]!==null&&s.lower[n]!==null){const u=s.upper[n]-s.lower[n];u>0&&(h[n]=(t[n]-s.lower[n])/u)}return h}export{D as a,R as b,I as c,C as d,V as e,S as f,B as g,L as h};
